# Mombe track 1a-v2: derived-cloud cache for fast local iteration.
# Generated by tools/kaggle/ruchay/build_kernel.py --cache. Do not edit by hand.
# Runs the frozen track 1a preprocessing (ruchay_bench.prepare: voxel 1 cm, RANSAC floor, level z-up,
# per-camera floor re-seat, footprint crop) and writes each animal's cropped cloud as float16 xyz
# (relative to a float64 offset) plus the camera id per point. No measurement runs here.
import base64, hashlib, json, os, subprocess, sys, tarfile, time, traceback

T0 = time.time()
OUT = "/kaggle/working"
WORK = "/tmp/ruchay"
os.makedirs(WORK + "/src", exist_ok=True)


def sh(cmd, check=True, keep=3000):
    print("$", cmd, flush=True)
    r = subprocess.run(cmd, shell=True, capture_output=True, text=True)
    if r.stdout:
        print(r.stdout[-keep:], flush=True)
    if r.stderr:
        print(r.stderr[-keep:], flush=True)
    if check and r.returncode != 0:
        raise SystemExit(f"command failed ({r.returncode}): {cmd}")
    return r


sh("df -h /tmp /kaggle/working; nproc; free -g", check=False)
for pkg in ("opencv-contrib-python-headless==5.0.0.93", "opencv-contrib-python==5.0.0.93"):
    if sh(f"pip install -q {pkg}", check=False).returncode == 0:
        break

MEASURE_B64 = ""
BENCH_B64 = ""
MEASURE_SHA256 = "d455283dae4577e96b8c14ddd5d6cf884d046af8562ef170201473a22f48f76d"
BENCH_SHA256 = "9c34664e4e2ef6c9fe78aa6aa11ee9c332f04d7968ca345d62f04690fa92e5c0"
mb, bb = base64.b64decode(MEASURE_B64), base64.b64decode(BENCH_B64)
assert hashlib.sha256(mb).hexdigest() == MEASURE_SHA256 and hashlib.sha256(bb).hexdigest() == BENCH_SHA256
open(f"{WORK}/src/measure.py", "wb").write(mb)
open(f"{WORK}/src/ruchay_bench.py", "wb").write(bb)
sys.path.insert(0, f"{WORK}/src")
import numpy as np  # noqa: E402
import ruchay_bench as rb  # noqa: E402

# Data: public GitHub repos, no licence file. Research use; the derived clouds stay private.
sh(f"git clone --depth 1 --filter=blob:none --sparse https://github.com/ruchaya/CowDatabase {WORK}/CowDatabase")
sh(f"git -C {WORK}/CowDatabase sparse-checkout set AlignedClouds Matrices")
cdb_head = sh(f"git -C {WORK}/CowDatabase rev-parse HEAD").stdout.strip()
C2 = f"{WORK}/CowDatabase2"
os.makedirs(C2, exist_ok=True)
c2_head = sh("git ls-remote https://github.com/ruchaya/CowDatabase2 HEAD", check=False).stdout.split()
c2_head = c2_head[0] if c2_head else "HEAD"
RAW = f"https://raw.githubusercontent.com/ruchaya/CowDatabase2/{c2_head}"


def fetch(rel, dst, tries=4):
    import urllib.request
    for k in range(tries):
        try:
            urllib.request.urlretrieve(f"{RAW}/{rel}", dst)
            return os.path.getsize(dst)
        except Exception as e:
            print("retry", rel, e, flush=True)
            time.sleep(3 * (k + 1))
    return -1


def save(Q, view, prep, dst):
    off = Q.mean(0)
    np.savez_compressed(dst, xyz=(Q - off).astype(np.float16), off=off.astype(np.float64), view=view.astype(np.int8),
                        cams=np.asarray(prep["cams_levelled"], np.float64), R=np.asarray(prep["R"], np.float64))
    return hashlib.sha256(open(dst, "rb").read()).hexdigest()


def one(job):
    db, key, ply, mats_path, dst = job
    t0 = time.time()
    try:
        xyz, _ = rb.read_ply(ply)
        mats = rb.parse_matrices(open(mats_path).read()) if mats_path and os.path.exists(mats_path) else None
        P, v, info = rb.split_aligned(xyz, mats)
        prep = rb.prepare(P, v, np.array(info["sentinels"]))
        sha = save(prep["Q"], prep["view"], prep, dst)
        return {"db": db, "id": key, "ok": True, "sha256": sha, "n": int(len(prep["Q"])), "floor": prep["floor"],
                "view_floor": prep["view_floor"], "crop": prep["crop"], "split_info": info, "s": round(time.time() - t0, 1)}
    except Exception as e:
        traceback.print_exc()
        return {"db": db, "id": key, "ok": False, "reason": f"{type(e).__name__}: {e}"}


os.makedirs(f"{WORK}/cache/cdb", exist_ok=True)
os.makedirs(f"{WORK}/cache/cdb2", exist_ok=True)
jobs = [("cdb", i, f"{WORK}/CowDatabase/AlignedClouds/{i}_AutoAligned.ply", f"{WORK}/CowDatabase/Matrices/{i}.matrices",
         f"{WORK}/cache/cdb/{i}.npz") for i in range(1, 104)]
fetch("Database2022v2.xlsx", f"{C2}/Database2022v2.xlsx")
frames = sorted(rb.read_tape_cdb2(f"{C2}/Database2022v2.xlsx"))
for f in frames:
    os.makedirs(f"{C2}/{f}", exist_ok=True)
from concurrent.futures import ProcessPoolExecutor, ThreadPoolExecutor  # noqa: E402
with ThreadPoolExecutor(6) as ex:
    sizes = list(ex.map(lambda f: fetch(f"{f}/aligned.ply", f"{C2}/{f}/aligned.ply"), frames))
print("CowDatabase2 frames", len(frames), "bad sizes", [f for f, s in zip(frames, sizes) if s != 10421051], flush=True)
jobs += [("cdb2", f, f"{C2}/{f}/aligned.ply", None, f"{WORK}/cache/cdb2/{f}.npz") for f, s in zip(frames, sizes) if s > 0]
manifest = {"what": "track 1a preprocessing (ruchay_bench.prepare, frozen PARAMS) applied to every cloud; fused cameras; "
                    "levelled frame, floor z = 0, metres; xyz float16 relative to off (float64); view 0/1/2 = side A/top/side B",
            "params": {k: list(v) if isinstance(v, tuple) else v for k, v in rb.PARAMS.items()},
            "bench_sha256": BENCH_SHA256, "measure_sha256": MEASURE_SHA256, "repo_commit": "d697be9926e3b9d9a367e482b687f99cd2397d9f",
            "CowDatabase_commit": cdb_head, "CowDatabase2_commit": c2_head, "numpy": np.__version__, "animals": []}
with ProcessPoolExecutor(max(1, os.cpu_count() or 1)) as ex:
    for r in ex.map(one, jobs):
        manifest["animals"].append(r)
        print(r["db"], r["id"], r.get("ok"), r.get("n"), r.get("s"), r.get("reason", ""), f"t={time.time() - T0:.0f}s", flush=True)
json.dump(manifest, open(f"{OUT}/ruchay_cache_manifest.json", "w"), indent=1)
for db in ("cdb", "cdb2"):
    with tarfile.open(f"{OUT}/ruchay_cache_{db}.tar", "w") as tf:
        tf.add(f"{WORK}/cache/{db}", arcname=db)
sh(f"ls -la {OUT}", check=False)
print("done", sum(a["ok"] for a in manifest["animals"]), "of", len(manifest["animals"]), f"in {time.time() - T0:.0f}s")
